parameters.jsCode:
// Standardize the binary key to 'file' and declare the REAL container.
//
// This node used to hardcode webm/speech.webm onto whatever arrived. Safari
// (iPad/iPhone/macOS) records AAC in an MP4 container, so Groq was handed AAC
// bytes labelled as Opus; the decoder produced noise and Whisper's language
// detector assigned that noise an arbitrary language. Trust the incoming
// mimeType and map it onto an extension Groq accepts.
const EXT_BY_MIME = [
  [/^(audio|video)\/webm$/,                     'webm', 'audio/webm'],
  [/^(audio\/(mp4|m4a|x-m4a|aac)|video\/mp4)$/, 'm4a',  'audio/mp4'],
  [/^audio\/(mpeg|mp3)$/,                       'mp3',  'audio/mpeg'],
  [/^(audio|application)\/ogg$/,                'ogg',  'audio/ogg'],
  [/^audio\/(wav|wave|x-wav|vnd\.wave)$/,       'wav',  'audio/wav'],
  [/^audio\/(flac|x-flac)$/,                    'flac', 'audio/flac'],
];
const ALLOWED_EXT = ['webm', 'm4a', 'mp4', 'mp3', 'mpeg', 'mpga', 'ogg', 'wav', 'flac'];

const items = $input.all();
for (const item of items) {
  if (!item.binary) continue;
  const keys = Object.keys(item.binary);
  if (keys.length === 0) continue;

  const f = item.binary[keys[0]];
  item.binary.file = f;

  const declared = String(f.mimeType || '').split(';')[0].trim().toLowerCase();
  const hit = EXT_BY_MIME.find(([re]) => re.test(declared));

  let ext, mime;
  if (hit) {
    ext = hit[1];
    mime = hit[2];
  } else {
    // No usable content type. Fall back to the extension the client sent, and
    // only then to webm (what every non-Safari browser in this stack records).
    const sent = String(f.fileExtension || '').toLowerCase().replace(/^\./, '');
    ext = ALLOWED_EXT.includes(sent) ? sent : 'webm';
    mime = declared || 'application/octet-stream';
  }

  f.mimeType = mime;
  f.fileExtension = ext;
  f.fileName = 'speech.' + ext;

  item.json = item.json || {};
  item.json.audioMime = mime;
  item.json.audioExt = ext;
}
return items;

// Fence in Whisper's language auto-detect.
//
// Groq offers no "detect within this set" option, so we let it detect freely and
// reject the turn when the result falls outside the languages this deployment
// serves. A rejection surfaces as "please try again" in the UI instead of a
// foreign-language transcript being forwarded to the agent as a real question.
//
// Groq returns the language as a capitalised English NAME ("English", "Arabic"),
// not an ISO code, hence the lowercased lookup covering both spellings.
const ALLOWED = { en: 'en', eng: 'en', english: 'en', ar: 'ar', ara: 'ar', arabic: 'ar' };

const REJECT = 'That did not come through as English or Arabic. Please try again, '
             + 'a little closer to the microphone.';

function isArabicCode(n) {
  return (n >= 0x0600 && n <= 0x06ff)   // Arabic
      || (n >= 0x0750 && n <= 0x077f)   // Arabic Supplement
      || (n >= 0x08a0 && n <= 0x08ff)   // Arabic Extended-A
      || (n >= 0xfb50 && n <= 0xfdff)   // Presentation Forms-A
      || (n >= 0xfe70 && n <= 0xfeff);  // Presentation Forms-B
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const text = String(j.text || '').trim();
  const raw = String(j.language || '').trim().toLowerCase();
  const lang = ALLOWED[raw] || null;

  const letters = text.match(/\p{L}/gu) || [];
  let arabic = 0;
  let latin = 0;
  for (const ch of letters) {
    const n = ch.codePointAt(0);
    if (isArabicCode(n)) arabic++;
    else if ((n >= 65 && n <= 90) || (n >= 97 && n <= 122)) latin++;
  }
  const known = arabic + latin;
  const inScript = letters.length ? known / letters.length : 1;

  let error = null;
  if (!text || !/[\p{L}\p{N}]/u.test(text)) {
    error = "I didn't catch that - please try again.";
  } else if (!lang) {
    // The label itself is out of range - this is the reported iPad symptom,
    // where a mis-decoded clip came back tagged Vietnamese, Welsh, Nepali...
    error = REJECT;
  } else if (inScript < 0.6) {
    // Script the deployment does not serve (Cyrillic, CJK, Thai, Devanagari),
    // caught even when the label looks plausible.
    error = REJECT;
  } else if (known >= 4) {
    // Label and script must agree, but only overrule the label when the script
    // is unambiguous: a question that genuinely mixes the two ("أين يقع حرم IUL")
    // has to pass.
    const script = arabic / known >= 0.9 ? 'ar' : latin / known >= 0.9 ? 'en' : null;
    if (script && script !== lang) error = REJECT;
  }

  // Diagnostics only - do NOT gate on these. whisper-large-v3-turbo on Groq
  // reports no_speech_prob 0 even for two seconds of pure digital silence
  // (measured 2026-09-01), and a silence hallucination's avg_logprob (-0.29)
  // sits too close to real speech (-0.16) to separate them. Silent clips are
  // stopped in the browser instead, by the peak-level gate in hooks/useSTT.ts.
  const num = (v) => (typeof v === 'number' ? v : null);
  const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
  const segs = Array.isArray(j.segments) ? j.segments : [];

  out.push({
    json: {
      text: error ? '' : text,
      language: error ? null : lang,
      detectedLanguage: raw || null,
      inScript,
      noSpeechProb: mean(segs.map((s) => num(s.no_speech_prob)).filter((v) => v !== null)),
      avgLogprob: mean(segs.map((s) => num(s.avg_logprob)).filter((v) => v !== null)),
      error,
    },
  });
}
return out;
